//! Parity between the whole speak run in `voxr_narrate` ([`speak_script`])
//! and the JavaScript `speak` it ports.
//!
//! The fixture (`tests/fixtures/narration_dispatch_oracle.json`) is
//! checked in and was generated by
//! `tests/tools/narration_oracle/take_dispatch.mjs`, which runs a patched
//! copy of the skill's own `speak` end to end with the config, VoxCPM2's
//! readiness, the engines, the recognizer and the VoxCPM2 run stubbed. The
//! cases cover the default engine pick, tags stripped and kept, every
//! VoxCPM2 option from the flags and the config, a reference, the device
//! and readiness error, a time-stretch on a command and on a model, a speed
//! on Kokoro and on `--engine kokoro` with a command, timed lines placed
//! late and over their slot, a one-call command's timed lines, timed lines
//! stretched, timed lines with VoxCPM2 and with Kokoro, and the invalid
//! engine and speed errors.
//!
//! Each case here runs [`speak_script`] over the same options, replays the
//! recorded engine calls, and compares every engine call, every option the
//! command and the VoxCPM2 run get, every line printed, every recognizer
//! call, the result as JSON, and the length and 16-bit data of the final
//! WAV, or the error. A case through ffmpeg's resampler compares its data
//! exactly on a CPU with AVX2 and FMA, the path `voxr::resample_like_ffmpeg`
//! reproduces bit for bit. On any other CPU it compares against a live
//! ffmpeg run of the same steps, within float rounding. Without the
//! `stretch` feature, a case that stretches or resamples checks that the
//! run names the feature.

use std::collections::VecDeque;
use std::path::{Path, PathBuf};

use serde::Deserialize;
use serde_json::Value;
use voxr_narrate::{
    EngineChoice, Error, HeardWord, Hearing, JoinedTrack, PartCheck, Recognizer, Result,
    ScriptStep, SimpleRun, SimpleSetup, SimpleStep, SpeakOpts, SpeakRequest, SpeakRuns,
    SpeakTarget, SpeechEngine, Take, TimedCue, Transcribed, TtsConfig, VoiceSource, VoxcpmRun,
    VoxcpmSetup, pcm16_wav, speak_phrases, speak_script,
};

mod common;
#[cfg(feature = "stretch")]
use common::ffmpeg;
use common::signals::{fnv1a, fnv1a_bytes};
use common::take_files::{OpJson, io, render_json};
use common::{assert_oracle_current, load_json};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_dispatch_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/take_dispatch.mjs"
);

/// The placeholder the oracle writes for a case's directory.
const DIR: &str = "<dir>";

#[derive(Debug, Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    script: String,
    opts: OptsJson,
    tts: TtsJson,
    ready: bool,
    why: String,
    hear: Vec<Heard>,
    resampled: bool,
    calls: Vec<CallJson>,
    commands: Vec<CommandJson>,
    voxcpm: Option<VoxcpmJson>,
    messages: Vec<String>,
    heard: Vec<HeardCall>,
    out: Option<OutJson>,
    error: Option<String>,
    result: Option<String>,
}

#[derive(Debug, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
struct OptsJson {
    engine: Option<String>,
    command: Option<String>,
    model: Option<String>,
    voice: Option<String>,
    reference: Option<String>,
    language: Option<String>,
    speed: Option<f64>,
    style: Option<String>,
    hifi: Option<bool>,
    cfg: Option<f64>,
    steps: Option<u32>,
    device: Option<String>,
    seed: Option<f64>,
    #[serde(default)]
    reroll: Vec<usize>,
    one_call: Option<bool>,
    cues: Option<Vec<CueJson>>,
}

#[derive(Debug, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
struct TtsJson {
    engine: Option<String>,
    command: Option<String>,
    model: Option<String>,
    voice: Option<String>,
    speed: Option<f64>,
    reference: Option<String>,
    style: Option<String>,
    hifi: Option<bool>,
    cfg: Option<f64>,
    steps: Option<u32>,
    seed: Option<f64>,
    one_call: Option<bool>,
}

#[derive(Debug, Deserialize)]
struct CueJson {
    start: f64,
    end: Option<f64>,
    text: String,
}

#[derive(Debug, Clone, Deserialize)]
struct Heard {
    words: Vec<HeardWord>,
    looped: bool,
}

/// One Kokoro, model or command call: its text, voice, speed, rate and
/// tone.
#[derive(Debug, Deserialize)]
struct CallJson {
    text: String,
    voice: Option<String>,
    speed: Option<f64>,
    rate: u32,
    n: usize,
    ops: Vec<OpJson>,
}

/// The options `command()` is called with.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CommandJson {
    template: String,
    voice: String,
    reference: String,
    one_call: bool,
}

/// The VoxCPM2 stub's call: the script, the options `voxcpm()` gets, the
/// signal it writes and the result it returns.
#[derive(Debug, Deserialize)]
struct VoxcpmJson {
    script: String,
    opts: VoxcpmOpts,
    n: usize,
    ops: Vec<OpJson>,
    result: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct VoxcpmOpts {
    voice: String,
    reference: String,
    style: String,
    hifi: bool,
    cfg: f64,
    steps: u32,
    device: Option<String>,
    seed: Option<f64>,
    config_seed: Option<f64>,
    language: Option<String>,
    reroll: Vec<usize>,
    lines: bool,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
struct HeardCall {
    model: String,
    language: Option<String>,
    samples: String,
}

#[derive(Debug, Deserialize)]
struct OutJson {
    length: usize,
    pcm: String,
}

/// Every engine run of one case: each Kokoro, model or command call
/// replayed in turn, and the VoxCPM2 run stubbed as the oracle stubs it.
struct Runs<'a> {
    case: &'a Case,
    root: &'a str,
    at: usize,
    commands: usize,
    voxcpm: usize,
    hearing: ScriptedHearing,
    /// The last run's joined samples, their rate and its phrase spans.
    joined: Option<(Vec<f32>, u32, Option<Vec<HeardWord>>)>,
    /// Every step, in the order it happened.
    notes: Vec<ScriptStep>,
}

impl Runs<'_> {
    fn masked(&self, text: &str) -> String {
        text.replace(self.root, DIR)
    }
}

impl SpeakRuns for Runs<'_> {
    fn voxcpm(&mut self, script: &str, setup: &VoxcpmSetup<'_>) -> Result<VoxcpmRun> {
        let name = &self.case.name;
        self.voxcpm += 1;
        let want = self.case.voxcpm.as_ref().ok_or_else(|| Error::DataError {
            reason: format!("case {name} runs VoxCPM2, where the skill does not"),
        })?;
        let o = &want.opts;
        assert_eq!(script, want.script, "VoxCPM2 script, {name}");
        assert_eq!(setup.voice, o.voice, "voice, {name}");
        let reference = setup
            .reference
            .map(|r| self.masked(&r.path.to_string_lossy()));
        assert_eq!(
            reference.unwrap_or_default(),
            o.reference,
            "reference, {name}"
        );
        assert_eq!(setup.style, o.style, "style, {name}");
        assert_eq!(setup.hifi, o.hifi, "hifi, {name}");
        assert_eq!(setup.cfg, o.cfg, "cfg, {name}");
        assert_eq!(setup.steps, o.steps, "steps, {name}");
        assert_eq!(setup.device, o.device.as_deref(), "device, {name}");
        assert_eq!(setup.seed, o.seed, "seed, {name}");
        assert_eq!(setup.config_seed, o.config_seed, "config seed, {name}");
        assert_eq!(setup.language, o.language.as_deref(), "language, {name}");
        assert_eq!(setup.rerolls, o.reroll.as_slice(), "rerolls, {name}");
        assert_eq!(setup.lines, o.lines, "lines, {name}");
        let samples = render_json(want.n, &want.ops);
        std::fs::write(setup.out, pcm16_wav(&samples, 48000)?).map_err(io("writing", setup.out))?;
        let result: Value = serde_json::from_str(&want.result).map_err(|e| Error::DataError {
            reason: format!("case {name}: the VoxCPM2 result: {e}"),
        })?;
        let phrases: Vec<HeardWord> =
            serde_json::from_value(result["phrases"].clone()).map_err(|e| Error::DataError {
                reason: format!("case {name}: the VoxCPM2 phrases: {e}"),
            })?;
        let checks = result["checks"]
            .as_array()
            .map(|list| list.iter().map(part_check).collect())
            .unwrap_or_default();
        let voice_file = result["voiceFile"]
            .as_str()
            .map(|f| PathBuf::from(f.replace(DIR, self.root)));
        Ok(VoxcpmRun {
            seed: 7.0,
            parts: Vec::new(),
            track: JoinedTrack {
                duration: want.n as f64 / 48000.0,
                samples,
                phrases,
                starts: Vec::new(),
                heat: Vec::new(),
            },
            checks,
            problems: Vec::new(),
            voice_file,
            voice_median: 0.0,
            log: Vec::new(),
        })
    }

    fn phrases(&mut self, script: &str, setup: &SimpleSetup<'_>) -> Result<SimpleRun> {
        let name = &self.case.name;
        if let EngineChoice::Command {
            command,
            voice,
            reference,
        } = setup.engine
        {
            let want = self.case.commands.get(self.commands);
            self.commands += 1;
            let want =
                want.unwrap_or_else(|| panic!("case {name} runs a command the skill does not"));
            assert_eq!(command, &want.template, "template, {name}");
            assert_eq!(voice, &want.voice, "command voice, {name}");
            assert_eq!(
                &self.masked(reference),
                &want.reference,
                "command reference, {name}"
            );
            assert_eq!(setup.one_call, want.one_call, "one call, {name}");
        }
        let mut synth = Synth {
            case: self.case,
            at: self.at,
        };
        let notes = &mut self.notes;
        let mut steps = |s: SimpleStep| notes.push(ScriptStep::Phrases(s));
        let run = speak_phrases(script, setup, &mut synth, &mut self.hearing, &mut steps);
        self.at = synth.at;
        if let Ok(r) = &run {
            self.joined = Some((r.samples.clone(), r.rate, r.phrases.clone()));
        }
        run
    }

    fn note(&mut self, step: ScriptStep) {
        self.notes.push(step);
    }
}

/// A VoxCPM2 part's check as the stub returns it.
fn part_check(v: &Value) -> PartCheck {
    let text = |key: &str| v[key].as_str().unwrap_or_default().to_string();
    PartCheck {
        at: v["at"].as_f64().unwrap_or(f64::NAN),
        text: text("text"),
        ok: v["ok"].as_bool().unwrap_or(false),
        heard: text("heard"),
        why: text("why"),
        seed: v["seed"].as_f64().unwrap_or(f64::NAN),
        doubt: Vec::new(),
        heat: v["heat"].as_f64().unwrap_or(f64::NAN),
        hot_text: v["hotText"].as_str().map(str::to_string),
        pauses: Vec::new(),
        clicks: Vec::new(),
    }
}

/// Kokoro, the model or the command, speaking each recorded call's tone in
/// turn.
struct Synth<'a> {
    case: &'a Case,
    at: usize,
}

impl SpeechEngine for Synth<'_> {
    type Reference = ();

    fn speak(&mut self, request: &SpeakRequest<'_, ()>) -> Result<Take> {
        let name = &self.case.name;
        let call = self
            .case
            .calls
            .get(self.at)
            .ok_or_else(|| Error::DataError {
                reason: format!("case {name} speaks more than {} calls", self.at),
            })?;
        self.at += 1;
        assert_eq!(request.text, call.text, "text, {name}");
        let voice = match request.voice {
            VoiceSource::Named { name } => Some(name),
            _ => None,
        };
        assert_eq!(voice, call.voice.as_deref(), "voice, {name}");
        assert_eq!(request.speed, call.speed.unwrap_or(1.0), "speed, {name}");
        Ok(Take {
            samples: render_json(call.n, &call.ops),
            rate: call.rate,
        })
    }
}

/// Hears the case's scripted words in turn, and records every call.
struct ScriptedHearing {
    queue: VecDeque<Heard>,
    calls: Vec<HeardCall>,
}

impl Hearing for ScriptedHearing {
    fn hear(
        &mut self,
        take: &[f32],
        _rate: u32,
        recognizer: Recognizer,
        language: Option<&str>,
    ) -> Result<Transcribed> {
        let model = match recognizer {
            Recognizer::Default => "default",
            Recognizer::Small => "small",
            Recognizer::Configured => "configured",
        };
        self.calls.push(HeardCall {
            model: model.to_string(),
            language: language.map(str::to_string),
            samples: fnv1a(take),
        });
        let heard = self.queue.pop_front().unwrap_or(Heard {
            words: Vec::new(),
            looped: false,
        });
        Ok(Transcribed {
            words: heard.words,
            looped: heard.looped,
            duration: 0.0,
        })
    }
}

/// Every number as a double, so `3` and `3.0` compare equal.
fn doubles(v: Value) -> Value {
    match v {
        Value::Number(n) => n
            .as_f64()
            .and_then(serde_json::Number::from_f64)
            .map_or(Value::Null, Value::Number),
        Value::Array(list) => Value::Array(list.into_iter().map(doubles).collect()),
        Value::Object(map) => {
            Value::Object(map.into_iter().map(|(k, x)| (k, doubles(x))).collect())
        }
        other => other,
    }
}

fn parse(name: &str, text: &str) -> Value {
    doubles(serde_json::from_str(text).unwrap_or_else(|e| panic!("case {name}: JSON: {e}")))
}

/// The 16-bit data the WAV at `out` holds, behind its 44-byte header.
fn pcm_data(out: &Path) -> Result<Vec<u8>> {
    let bytes = std::fs::read(out).map_err(io("reading", out))?;
    assert_eq!(
        bytes.get(36..40),
        Some(&b"data"[..]),
        "data chunk of {}",
        out.display()
    );
    Ok(bytes[44..].to_vec())
}

/// Without the `stretch` feature, a run that stretches or resamples names
/// the feature, and nothing else of the case is checked.
fn needs_feature(err: &Error) -> bool {
    !cfg!(feature = "stretch")
        && matches!(err, Error::InvalidArgument { reason, .. } if reason.contains("`stretch` feature"))
}

fn check_case(case: &Case) -> Result<()> {
    let name = &case.name;
    let tmp = tempfile::tempdir().map_err(|e| Error::File {
        reason: format!("creating a temporary directory: {e}"),
    })?;
    let root = tmp.path().to_string_lossy().into_owned();
    let recording = tmp.path().join("ref.wav");
    std::fs::write(&recording, "a recording").map_err(io("writing", &recording))?;
    let out = tmp.path().join("out.wav");
    let o = &case.opts;
    let reference = o.reference.as_ref().map(|r| r.replace(DIR, &root));
    let cues: Option<Vec<TimedCue>> = o.cues.as_ref().map(|list| {
        list.iter()
            .map(|c| TimedCue {
                start: c.start,
                end: c.end,
                text: c.text.clone(),
            })
            .collect()
    });
    let opts = SpeakOpts {
        engine: o.engine.as_deref(),
        command: o.command.as_deref(),
        model: o.model.as_deref(),
        voice: o.voice.as_deref(),
        reference: reference.as_deref(),
        language: o.language.as_deref(),
        speed: o.speed,
        style: o.style.as_deref(),
        hifi: o.hifi,
        cfg: o.cfg,
        steps: o.steps,
        device: o.device.as_deref(),
        seed: o.seed,
        reroll: &o.reroll,
        one_call: o.one_call,
        cues: cues.as_deref(),
        stretched: false,
        lines: false,
    };
    let t = &case.tts;
    let tts = TtsConfig {
        engine: t.engine.as_deref(),
        command: t.command.as_deref(),
        model: t.model.as_deref(),
        voice: t.voice.as_deref(),
        speed: t.speed,
        reference: t.reference.as_deref(),
        style: t.style.as_deref(),
        hifi: t.hifi,
        cfg: t.cfg,
        steps: t.steps,
        seed: t.seed,
        one_call: t.one_call,
    };
    let target = SpeakTarget {
        asr_model: None,
        out: &out,
        cache_dir: tmp.path(),
        checkpoint: None,
        voxcpm_ready: case.ready,
        voxcpm_why: &case.why,
    };
    let mut runs = Runs {
        case,
        root: &root,
        at: 0,
        commands: 0,
        voxcpm: 0,
        hearing: ScriptedHearing {
            queue: case.hear.iter().cloned().collect(),
            calls: Vec::new(),
        },
        joined: None,
        notes: Vec::new(),
    };
    let got = speak_script(&case.script, &opts, &tts, &target, &mut runs);
    if let Err(e) = &got
        && needs_feature(e)
        && case.error.is_none()
    {
        eprintln!("case {name}: needs the stretch feature, as the run says: {e}");
        return Ok(());
    }
    assert_eq!(runs.at, case.calls.len(), "engine calls, {name}");
    assert_eq!(runs.commands, case.commands.len(), "command runs, {name}");
    assert_eq!(
        runs.voxcpm,
        usize::from(case.voxcpm.is_some()),
        "VoxCPM2 runs, {name}"
    );
    assert_eq!(runs.hearing.calls, case.heard, "recognizer calls, {name}");
    let spoken = match (got, &case.error) {
        (Err(Error::InvalidArgument { reason, .. }), Some(want)) => {
            assert!(
                want.ends_with(&reason),
                "error, {name}: {want:?} vs {reason:?}"
            );
            return Ok(());
        }
        (Err(e), _) => panic!("case {name} fails where the skill does not: {e}"),
        (Ok(_), Some(want)) => panic!("case {name} speaks, where the skill fails: {want}"),
        (Ok(spoken), None) => spoken,
    };
    let messages: Vec<String> = runs.notes.iter().filter_map(|s| s.message()).collect();
    assert_eq!(messages, case.messages, "messages, {name}");
    let json = serde_json::to_string(&spoken).map_err(|e| Error::DataError {
        reason: e.to_string(),
    })?;
    let want = case
        .result
        .as_deref()
        .unwrap_or_else(|| panic!("case {name} has no result"));
    assert_eq!(
        parse(name, &json.replace(&root, DIR)),
        parse(name, want),
        "result, {name}"
    );
    let want = case
        .out
        .as_ref()
        .unwrap_or_else(|| panic!("case {name} has no WAV"));
    let data = pcm_data(&out)?;
    assert_eq!(data.len() / 2, want.length, "WAV length, {name}");
    if !case.resampled || bit_exact() {
        assert_eq!(fnv1a_bytes(&data), want.pcm, "WAV data, {name}");
    } else {
        rounding_check(case, &runs, &data, cues.as_deref())?;
    }
    Ok(())
}

/// The CPU takes ffmpeg's AVX2 and FMA path, where its resampler and voxr's
/// agree bit for bit.
#[cfg(feature = "stretch")]
fn bit_exact() -> bool {
    ffmpeg::takes_fma_path()
}

/// Without the `stretch` feature, no resampled case reaches the data check.
#[cfg(not(feature = "stretch"))]
fn bit_exact() -> bool {
    true
}

/// A resampled case off the AVX2 and FMA path: the final WAV's `data`
/// against a live ffmpeg run of the same steps over the same joined
/// samples, within [`ffmpeg::MIN_ROUNDING_SNR_DB`]. The time-stretch runs
/// ffmpeg's `atempo` and `-ar 48000`, a plain decode runs `-ar 48000`, and
/// timed lines are then placed on that track.
#[cfg(feature = "stretch")]
fn rounding_check(
    case: &Case,
    runs: &Runs<'_>,
    data: &[u8],
    cues: Option<&[TimedCue]>,
) -> Result<()> {
    use voxr_narrate::{CueUnits, PLACE_RATE, pcm16_round_trip, place_on_times, stretch_phrases};

    let name = &case.name;
    let Some(bin) = ffmpeg::bin() else {
        ffmpeg::skip_notice();
        return Ok(());
    };
    let (samples, rate, phrases) = runs
        .joined
        .as_ref()
        .unwrap_or_else(|| panic!("case {name}: a resampled case runs no engine but VoxCPM2"));
    let wav = pcm16_wav(samples, *rate)?;
    let speed = case.opts.speed.or(case.tts.speed).unwrap_or(1.0);
    let (track, spans) = if speed == 1.0 {
        (ffmpeg::decode_48k(&bin, &wav), phrases.clone())
    } else {
        let spans = phrases.as_ref().map(|p| stretch_phrases(p, speed));
        (ffmpeg::stretch(&bin, &wav, speed), spans)
    };
    let reference = match cues {
        Some(cues) => {
            let spans = spans.unwrap_or_else(|| panic!("case {name}: timed lines with no spans"));
            let placed = place_on_times(&track, PLACE_RATE, &spans, cues, CueUnits::Phrases)?;
            pcm16_round_trip(&placed.samples)
        }
        None => track,
    };
    let ours: Vec<f32> = data
        .as_chunks::<2>()
        .0
        .iter()
        .map(|&b| f32::from(i16::from_le_bytes(b)) / 32768.0)
        .collect();
    ffmpeg::check_snr(name, &reference, &ours);
    Ok(())
}

#[cfg(not(feature = "stretch"))]
fn rounding_check(case: &Case, _: &Runs<'_>, _: &[u8], _: Option<&[TimedCue]>) -> Result<()> {
    panic!(
        "case {}: a resampled case reached the data check without the stretch feature",
        case.name
    );
}

#[test]
fn matches_javascript_on_every_case() -> Result<()> {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    for case in &fixture.cases {
        check_case(case)?;
    }
    Ok(())
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
